const [tz, setTz] = useState("Europe/Berlin");

<Combobox
  label="Time zone"
  name="tz"
  placeholder="Search time zones"
  options={[
    { label: "Europe", options: [
      { value: "Europe/Lisbon", label: "Lisbon", description: "UTC+0" },
      { value: "Europe/Berlin", label: "Berlin", description: "UTC+1" },
    ] },
    { label: "Americas", options: [
      { value: "America/Bogota", label: "Bogotá", description: "UTC−5" },
      { value: "America/Sao_Paulo", label: "São Paulo", description: "UTC−3", keywords: ["Brasil"] },
    ] },
  ]}
  value={tz}
  onChange={(value) => setTz(value)}
  required
/>

